            detail: "The direct reward requires viewing Treno Tradition. If he passes Steiner and exits the building, this early reward is lost. Power Belt can still be synthesized later from Glass Buckle + Chain Mail for 2,000 Gil, so this is an early-access warning rather than permanent loss of the item type.",
