    timedRouteNote: "The EII route reaches Desert Palace Rack at 08:36:57 after Cid's escape game and Mogsam's letter. The source's six-minute minigame clock resets; pausing stops the cumulative game timer on the PlayStation route. D3-07 takes the Promist Ring from its bloodstone (the 10th copy only after the optional +21:00 Treno auction detour), sweeps Fairy Earrings and the remaining bloodstone gear, collects the final Namingway Card, and defeats Valia Pira before reaching Esto Gaza at 08:52:28 (2 random encounters). The baseline excludes the Treno detour. This timed sweep is separate from the broad standard-route pickup route and is not independently timed.",
