    areaId: "disc-3.ipsens-castle",
    overview: "Land at Ipsen's Castle on the northwestern Forgotten Continent after any open-world stops you want to finish. Adapt the party to the castle's reversed weapon rule, check Kumool's letter and shop, collect the route treasures, solve the fresco and pot puzzles, take the four mirrors, and defeat Taharka. Sweep the post-boss items, leave once, then return alone to find Amarant. The castle can be revisited; Taharka's steal table is the only one-time encounter opportunity in this chapter.",
    timedRouteNote: "D3-10 begins at Ipsen's Castle at 09:25:45. The source route follows the weak-weapon rule and its treasure/letter route, steals Orichalcon from Taharka, exits once, then returns for Amarant. Do not leave a selected local collection goal behind when following the source's fast route; this segment has 0 random encounters and continues into the four shrines. These are source targets, not independently timed.",
