            detail: "A Kupo Nut can only be carried one at a time. GameFAQs lists Mage Masher (500 Gil), Iron Sword (660), Mythril Spear (1,100), Poison Knuckles (7,000), Multina Racket (750), Mythril Rod (560), Lamia's Flute (3,800), Oak Staff (2,400), Rising Sun (500), N-Kai Armlet (3,000), Jade Armlet (3,400), Venetia Shield (2,800), Red Hat (3,000), Golden Hairpin (3,700), Coronet (4,400), Cross Helm (2,200), Diamond Helm (3,000), Power Vest (7,200), Gaia Gear (8,700), Shield Armor (4,300), and Demon's Mail (5,900). GameFAQs Items and RPGClassics add Needle Fork (3,100), omitted by the GameFAQs Shops table. RPGClassics lists Poison Knuckles for 5,000 Gil, versus GameFAQs Shops' 7,000; the Coronet listing appears only in GameFAQs Shops, not GameFAQs Items or RPGClassics. Kumool's 12 listed supplies are Potion (50 Gil), Hi-Potion (200), Phoenix Down (150), Echo Screen (50), Soft (100), Antidote (50), Eye Drops (50), Magic Tag (100), Remedy (300), Vaccine (100), Annoyntment (150), and Tent (800). RPGClassics corroborates the other eleven Ipsen supplies but omits Remedy. The catalog preserves those source differences. It also keeps GameFAQs Items' optional Need and end-inventory counts separate from story requirements; Rising Sun has no such counts in that table. The castle can be revisited, but exact post-story Mogshop stock access has not been independently verified. Mythril Rod teaches Dagger Life, Silence, and Shell.",
