    areaId: "disc-4.return-to-gaia",
    overview: "After escaping Terra aboard the Invincible, return to a Mist-covered Gaia and use the airship to finish selected sidequests, revisit the world map, and collect newly available Disc IV rewards. Complete the Nero Family opening checkpoint before starting the final dungeon, then continue to the glowing entrance at the Iifa Tree when ready.",
    timedRouteNote: "The source's D4-01 schedule reaches the Memoria entrance at 10:40:40, including a first Tantalus Hideout trip for Nero Family checkpoint 1 (+02:30) and the return route for checkpoint 2 after Nova Dragon (+02:40). Its target reports 0 random encounters for this segment. The wider Disc IV Chocobo, frog, card, and collection routes are not part of this timed split; plan them separately. Earlier windows for Morrid's Coffees, Conde Petie's Colored Stones, Dali's Oglop trade, and Treno's Amdusias stage have already closed.",
