    timedRouteNote: "Excalibur II is available after Lich only when the total save timer is below 12:00:00. The original PlayStation NTSC Perfect Game reference targets Memoria — The Past at 11:01:10 (4 random encounters), the portal at 11:06:12 (1), Time Warp at 11:10:59 (0), and the pickup after Lich at 11:13:07. It takes The Tower and Rune Claws and steals Genji Armor from Maliris, Blood Sword from Tiamat, Genji Helmet from Kraken, and Genji Gloves from Lich before ending each battle. These are source targets, not independently timed; PAL, modern releases, boosters, alternative stat paths, and the wider collection route need separate verification.",
